-- Restore the public Mavo Nechasim inventory in a fresh Supabase project.
-- The seed comes only from the already-public properties.json dataset.

create table if not exists public.properties (
  id bigint generated by default as identity primary key,
  identity_fingerprint text unique,
  type text not null default 'rent',
  price text not null default '',
  price_label text not null default '',
  title text not null default '',
  location text not null default '',
  rooms numeric,
  baths numeric,
  sqm text not null default '',
  extra text not null default '',
  description text not null default '',
  emoji text not null default '🏠',
  bg text not null default 'linear-gradient(135deg,#1565C0,#0a0f1e)',
  lat double precision,
  lng double precision,
  photos jsonb not null default '[]'::jsonb check (jsonb_typeof(photos) = 'array'),
  has_elevator boolean not null default false,
  has_shelter boolean not null default false,
  has_parking boolean not null default false,
  active boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.properties enable row level security;
drop policy if exists "public reads active properties" on public.properties;
create policy "public reads active properties"
  on public.properties for select to anon, authenticated
  using (active = true);

insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types)
values ('property-photos','property-photos',true,20971520,array['image/jpeg','image/png','image/webp'])
on conflict (id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

drop policy if exists "public reads property photos" on storage.objects;
create policy "public reads property photos"
  on storage.objects for select to anon, authenticated
  using (bucket_id = 'property-photos');

