סות | מטבח עם גז | משופצת | מקלט קרוב","description":"דירת 3 חדרים מרווחת, מוארת מאוד ומשופצת בשפירא, בלוקיישן שקט בשכונה. עם 2 מרפסות, מטבח נפרד עם גז, מתאימה ל־2 שותפים, בבניין משופץ עם קודן ומקלט קרוב. כניסה מיידית. לפרטים ותיאום סיור: מאור בצלאל 054-802-6123.","emoji":"🏠","bg":"linear-gradient(135deg,#1565C0,#0a0f1e)","photos":["https://media.postify.co.il/postify157/bar_yochai_72/1-img_6a37a0ecc41ca.jpg","https://media.postify.co.il/postify157/bar_yochai_72/2-img_6a37a0ee30a53.jpg","https://media.postify.co.il/postify157/bar_yochai_72/3-img_6a37a0ef3f023.jpg","https://media.postify.co.il/postify157/bar_yochai_72/4-img_6a37a0f0841e4.jpg","https://media.postify.co.il/postify157/bar_yochai_72/5-img_6a37a0f17a101.jpg","https://media.postify.co.il/postify157/bar_yochai_72/6-img_6a37a0f29a41b.jpg","https://media.postify.co.il/postify157/bar_yochai_72/7-img_6a37a0f4045f6.jpg","https://media.postify.co.il/postify157/bar_yochai_72/8-img_6a37a0f557e75.jpg"],"has_elevator":false,"has_shelter":false,"has_parking":false,"active":true}]$seed$::jsonb) as x(
    id bigint, type text, price text, price_label text, title text, location text,
    lat double precision, lng double precision, rooms numeric, baths numeric,
    sqm text, extra text, description text, emoji text, bg text, photos jsonb,
    has_elevator boolean, has_shelter boolean, has_parking boolean, active boolean
  )
)
insert into public.properties (
  id,type,price,price_label,title,location,lat,lng,rooms,baths,sqm,extra,description,
  emoji,bg,photos,has_elevator,has_shelter,has_parking,active
)
select id,type,price,price_label,title,location,lat,lng,rooms,baths,sqm,extra,description,
       emoji,bg,photos,has_elevator,has_shelter,has_parking,active
from seed
on conflict (id) do update set
  type=excluded.type,price=excluded.price,price_label=excluded.price_label,title=excluded.title,
  location=excluded.location,lat=excluded.lat,lng=excluded.lng,rooms=excluded.rooms,
  baths=excluded.baths,sqm=excluded.sqm,extra=excluded.extra,description=excluded.description,
  emoji=excluded.emoji,bg=excluded.bg,photos=excluded.photos,
  has_elevator=excluded.has_elevator,has_shelter=excluded.has_shelter,
  has_parking=excluded.has_parking,active=excluded.active,updated_at=now();

select setval(
  pg_get_serial_sequence('public.properties','id'),
  greatest((select coalesce(max(id),0) from public.properties),1),
  true
);
